{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Faropenem, a penem sharing the 6-(1-hydroxyethyl) core with the query, has 72-84% oral bioavailability in children, directly supporting that this penem scaffold can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Cefuroxime axetil, an acyloxyalkyl ester prodrug with a 3-carbamoyloxymethyl group like the query, has 64% absolute oral bioavailability in humans, supporting the oral prodrug design.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "The beta-lactam ester prodrug DZ-2640 shows at least greater than 30% oral bioavailability in human volunteers, indicating that this class of esterified beta-lactams can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Pivampicillin, an acyloxymethyl ester prodrug of a beta-lactam, has 82% absolute oral bioavailability in humans, supporting the effectiveness of the ester prodrug strategy used in the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Cefditoren, a cephalosporin ester prodrug, has only about 14% fasting oral bioavailability in humans, providing a contradictory example that some beta-lactam ester prodrugs fall below 20%, though its structural similarity to the query is limited.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an orally oriented penem ester prodrug. The closest structural analogue, faropenem, shows high oral bioavailability (72-84%), and related beta-lactam ester prodrugs such as cefuroxime axetil, DZ-2640, and pivampicillin also exceed 20%. The low-F example cefditoren and general carbapenem oral-absorption concerns are less transferable because of structural and class differences. Overall, the evidence supports F >= 20%.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for this exact penem ester prodrug.",
    "Intestinal stability, hydrolysis of the acetoxymethyl ester, and possible transporter/efflux effects for the query are not directly measured.",
    "Cefditoren shows that acyloxyalkyl ester prodrugs in the broader beta-lactam class can have low F, so formulation and species effects remain an uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

